pub struct KMFBuilder<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> {
    fbb_: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    start_: ::flatbuffers::WIPOffset<::flatbuffers::TableUnfinishedWIPOffset>,
}

impl<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> KMFBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_KEY_ID(&mut self, KEY_ID: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(KMF::VT_KEY_ID, KEY_ID);
    }

    #[inline]
    pub fn add_ROLE(&mut self, ROLE: keyMaterialRole) {
        self.fbb_.push_slot::<keyMaterialRole>(KMF::VT_ROLE, ROLE, keyMaterialRole::Unknown);
    }

    #[inline]
    pub fn add_ALGORITHM(&mut self, ALGORITHM: keyMaterialAlgorithm) {
        self.fbb_.push_slot::<keyMaterialAlgorithm>(KMF::VT_ALGORITHM, ALGORITHM, keyMaterialAlgorithm::Unknown);
    }

    #[inline]
    pub fn add_ENCODING(&mut self, ENCODING: keyMaterialEncoding) {
        self.fbb_.push_slot::<keyMaterialEncoding>(KMF::VT_ENCODING, ENCODING, keyMaterialEncoding::Unknown);
    }

    #[inline]
    pub fn add_KEY_BYTES(&mut self, KEY_BYTES: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , u8>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(KMF::VT_KEY_BYTES, KEY_BYTES);
    }

    #[inline]
    pub fn add_VERSION(&mut self, VERSION: u32) {
        self.fbb_.push_slot::<u32>(KMF::VT_VERSION, VERSION, 0);
    }

    #[inline]
    pub fn add_EXPIRES_AT(&mut self, EXPIRES_AT: u64) {
        self.fbb_.push_slot::<u64>(KMF::VT_EXPIRES_AT, EXPIRES_AT, 0);
    }

    #[inline]
    pub fn new(_fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>) -> KMFBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        KMFBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }

    #[inline]
    pub fn finish(self) -> ::flatbuffers::WIPOffset<KMF<'a>> {
        let o = self.fbb_.end_table(self.start_);
        ::flatbuffers::WIPOffset::new(o.value())
    }
}

impl ::core::fmt::Debug for KMF<'_> {
    fn fmt(&self, f: &mut ::core::fmt::Formatter<'_>) -> ::core::fmt::Result {
        let mut ds = f.debug_struct("KMF");
        ds.field("KEY_ID", &self.KEY_ID());
        ds.field("ROLE", &self.ROLE());
        ds.field("ALGORITHM", &self.ALGORITHM());
        ds.field("ENCODING", &self.ENCODING());
        ds.field("KEY_BYTES", &self.KEY_BYTES());
        ds.field("VERSION", &self.VERSION());
        ds.field("EXPIRES_AT", &self.EXPIRES_AT());
        ds.finish()
    }
}

#[non_exhaustive]
#[derive(Debug, Clone, PartialEq)]
pub struct KMFT {
    pub KEY_ID: Option<alloc::string::String>,
    pub ROLE: keyMaterialRole,
    pub ALGORITHM: keyMaterialAlgorithm,
    pub ENCODING: keyMaterialEncoding,
    pub KEY_BYTES: Option<alloc::vec::Vec<u8>>,
    pub VERSION: u32,
    pub EXPIRES_AT: u64,
}

impl Default for KMFT {
    fn default() -> Self {
        Self {
            KEY_ID: None,
            ROLE: keyMaterialRole::Unknown,
            ALGORITHM: keyMaterialAlgorithm::Unknown,
            ENCODING: keyMaterialEncoding::Unknown,
            KEY_BYTES: None,
            VERSION: 0,
            EXPIRES_AT: 0,
        }
    }
}

impl KMFT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<KMF<'b>> {
        let KEY_ID = self.KEY_ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let ROLE = self.ROLE;
        let ALGORITHM = self.ALGORITHM;
        let ENCODING = self.ENCODING;
        let KEY_BYTES = self.KEY_BYTES.as_ref().map(|x|{
            _fbb.create_vector(x)
        });
        let VERSION = self.VERSION;
        let EXPIRES_AT = self.EXPIRES_AT;
        KMF::create(_fbb, &KMFArgs{
            KEY_ID,
            ROLE,
            ALGORITHM,
            ENCODING,
            KEY_BYTES,
            VERSION,
            EXPIRES_AT,
        })
    }
}

/// Verifies that a buffer of bytes contains a `KMF`
