/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_kmf_unchecked`.
#[inline]
pub fn root_as_kmf(buf: &[u8]) -> Result<KMF<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<KMF>(buf)
}

